package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import java.util.regex.*;
/** Original decimal dividends divided by whole numbers, including exact nonterminating quotients. */
public final class DecimalWholeQuotients {
 private DecimalWholeQuotients(){}
 public static final String ID="decimalDivInt";
 public record Givens(String raw,int divisor){}
 static boolean selected(String id,CurriculumLimits limits){return ID.equals(id)&&limits.variedFacts();}
 public static Givens read(Question q){if(q==null||!ID.equals(q.skillId)||q.prompt==null)return null;Matcher m=Pattern.compile("(\\d{1,2}\\.\\d{1,3}) [÷/] (\\d{1,2})").matcher(q.prompt);if(!m.matches())return null;int d=Integer.parseInt(m.group(2));return d>0?new Givens(m.group(1),d):null;}
 private static Rational result(Givens v){return Expression.number(v.raw).div(Rational.of(v.divisor));}
 private static boolean terminates(Givens v){try{new BigDecimal(v.raw).divide(BigDecimal.valueOf(v.divisor));return true;}catch(ArithmeticException e){return false;}}
 static Question make(String raw,int divisor){Question q=new Question(ID,raw+" ÷ "+divisor,"","0");Givens v=read(q);if(v==null)throw new IllegalArgumentException("Selected decimal/whole quotient scope");boolean finite=terminates(v);q.answers[0]=finite?new BigDecimal(raw).divide(BigDecimal.valueOf(divisor)).stripTrailingZeros().toPlainString():result(v).toString();q.answerFormat=finite?"decimalValue":"fraction";q.decimal=true;q.stepSupport=false;attach(q);return q.withInputs(Expression.number(raw),Rational.of(divisor));}
 static Question next(Random random,CurriculumLimits limits,Map<String,Integer> recent){int max=limits.wholeMaximum(99),precision=limits.decimalPlaces(3);if(max<0||max>99||precision<1||precision>3)throw new IllegalArgumentException("Selected decimal/whole quotient supply");int p=1+random.nextInt(precision),count=(max+1)*(int)Math.pow(10,p)*99;return IndexedQuestionSupply.choose(count,i->make(BigDecimal.valueOf(i/99,p).toPlainString(),i%99+1),random,limits,recent);}
 static Checker.Result check(Question q,List<String> answers){Givens v=read(q);if(v==null||answers==null||answers.size()!=1||answers.get(0)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수 입력 필요");String input=Expression.normalize(answers.get(0).trim());if(input.length()>120||!input.matches("[+-]?\\d+(?:\\.\\d+)?(?:/[+-]?\\d+)?"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수로 입력 필요");if("decimal".equals(q.answerFormat)&&(!input.contains(".")||input.contains("/")))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"소수로 입력 필요");if("decimalValue".equals(q.answerFormat)&&input.contains("/"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"소수로 입력 필요");try{boolean same=Expression.number(input).equals(result(v));return new Checker.Result(same?Checker.Status.CORRECT:Checker.Status.WRONG_ANSWER,same?-1:0,same?"계산 확인 완료":"이 계산 확인");}catch(RuntimeException e){return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수 입력 확인 필요");}}
 public static void attach(Question q){Givens v=read(q);if(v==null)return;if(terminates(v)){DecimalArithmeticRelations.attach(q);return;}BigDecimal x=new BigDecimal(v.raw);int p=x.scale(),scale=(int)Math.pow(10,p),a=x.movePointRight(p).intValue(),den=scale*v.divisor,gcd=Generator.gcd(a,den);StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="decimal-whole-quotient-v1";h.step("나누어지는 수를 쓰세요.","나누어지는 수 x = ","",v.raw);h.frames.get(0).inputFormat="decimalValue";h.step("나누는 수를 쓰세요.","나누는 수 d = ","",""+v.divisor);h.step("왼쪽 수의 소수점 아래 자릿수를 쓰세요.","옮길 자릿수 p = ","",""+p);h.step("옮길 자릿수에 맞는 자릿값 배수를 쓰세요.","자릿값 배수 u = ","",""+scale);h.step("소수점을 옮겨 나누어지는 수를 정수로 쓰세요.","옮긴 수 A = x × u = ","",""+a);h.step("자릿값 배수에 나누는 수를 곱해 분모를 구하세요.","분모 D = u × d = ","",""+den);h.step("분자와 분모의 최대공약수를 구하세요.","최대공약수 g = gcd(A, D) = ","",""+gcd);h.step("옮긴 수를 최대공약수로 나누어 분자를 구하세요.","분자 n = A ÷ g = ","",""+(a/gcd));h.step("분모를 같은 최대공약수로 나누세요.","분모 b = D ÷ g = ","",""+(den/gcd));q.studyGuide=h.fractionResult(7,8);}
}
